create or replace function public.get_quiz_questions(p_level public.jlpt_level,p_skill public.content_skill default null,p_limit integer default 10) returns table(id uuid,prompt text,choices jsonb,level public.jlpt_level,skill public.content_skill,explanation_id text,explanation_en text) language sql stable security invoker set search_path=public as $$ select q.id,q.prompt,q.choices,q.level,q.skill,q.explanation_id,q.explanation_en from public.questions q where q.is_published=true and q.level=p_level and (p_skill is null or q.skill=p_skill) order by q.created_at limit greatest(1,least(coalesce(p_limit,10),100)); $$; create or replace function public.record_quiz_attempt(p_quiz_id uuid,p_level public.jlpt_level,p_skill public.content_skill,p_total_questions integer,p_correct_count integer,p_duration_seconds integer default 0) returns public.quiz_attempts language plpgsql security invoker set search_path=public as $$ declare v_attempt public.quiz_attempts; v_xp integer; v_score numeric(5,2); begin if auth.uid() is null then raise exception 'Authentication required'; end if; if p_total_questions<=0 then raise exception 'total_questions must be positive'; end if; if p_correct_count<0 or p_correct_count>p_total_questions then raise exception 'correct_count is invalid'; end if; v_score:=round((p_correct_count::numeric/p_total_questions::numeric)*100,2); v_xp:=p_correct_count*10; insert into public.quiz_attempts(user_id,quiz_id,level,skill,total_questions,correct_count,score,xp_earned,duration_seconds) values(auth.uid(),p_quiz_id,p_level,p_skill,p_total_questions,p_correct_count,v_score,v_xp,greatest(coalesce(p_duration_seconds,0),0)) returning * into v_attempt; return v_attempt; end; $$; grant execute on function public.get_quiz_questions(public.jlpt_level,public.content_skill,integer) to authenticated; grant execute on function public.record_quiz_attempt(uuid,public.jlpt_level,public.content_skill,integer,integer,integer) to authenticated;
